csc = []

for i in range(0, 45002):
    csc.append(i * (i + 1) // 2)

def solve(csc, x):
    for i in range(45000):
        if csc[i] >= x:
            diff = csc[i] - x
            if diff % 2 == 0:
                return i
            else:
                diff2 = csc[i + 1] - x
                if diff2 % 2 == 0:
                    return i + 1
                else:
                    return i + 2

print(solve(csc, x))

