class Solve:

    def __init__(self) -> None:
        self.x = 0;
        self.dem = 0;

    def vao(self) -> None:
        self.x = int(input());

    def lam(self) -> None:
        tong = 0;
        x = abs(self.x);
        while(tong < x or (tong - x) % 2 != 0):
            self.dem += 1;
            tong += self.dem;

    def ra(self) -> None:
        print(self.dem);


def main():
    p = Solve();
    p.vao();
    p.lam();
    p.ra();

main();

